// src/core/city/city-readiness/city-readiness.routes.ts
// Rotas READ-ONLY para verificação de prontidão de cidade

import { FastifyPluginAsync } from 'fastify';
import { cityReadinessService } from './city-readiness.service';

const cityReadinessRoutes: FastifyPluginAsync = async (fastify) => {
  /**
   * GET /city-readiness/:cityId
   * Obtém prontidão de uma cidade
   * READ-ONLY: apenas diagnóstico, não executa nada
   */
  fastify.get<{
    Params: { cityId: string };
  }>('/:cityId', async (req, reply) => {
    const { cityId } = req.params;

    const result = await cityReadinessService.getCityReadiness(cityId);

    if (!result) {
      return reply.status(404).send({
        error: 'Cidade não encontrada',
      });
    }

    return reply.send(result);
  });
};

export default cityReadinessRoutes;











